// Parse RSS/Atom XML into normalized article items
const response = $input.item.json;
const xml = typeof response === 'string' ? response : (response.data || response.body || JSON.stringify(response));
const feedMeta = $('Loop Feeds').first().json;

if (!xml || xml.length < 100) return [];

const items = [];
const now = new Date();
const cutoff = new Date(now.getTime() - 48 * 60 * 60 * 1000); // 48hr window

// Extract <item> (RSS) or <entry> (Atom) blocks
const blockRegex = /<item[\s>][\s\S]*?<\/item>|<entry[\s\S]*?<\/entry>/gi;
const blocks = xml.match(blockRegex) || [];

function extractTag(block, tag) {
  const cdataRe = new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>`, 'i');
  const plainRe = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`, 'i');
  const m = block.match(cdataRe) || block.match(plainRe);
  return m ? m[1].trim() : '';
}

function extractLink(block) {
  // Atom: <link href="..." />
  const atomLink = block.match(/<link[^>]*href=["']([^"']+)["'][^>]*\/?>/i);
  if (atomLink) return atomLink[1];
  // RSS: <link>...</link>
  return extractTag(block, 'link');
}

function stripHtml(str) {
  return str.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

for (const block of blocks.slice(0, 15)) {
  const title = stripHtml(extractTag(block, 'title'));
  const link = extractLink(block);
  const desc = stripHtml(
    extractTag(block, 'description') ||
    extractTag(block, 'summary') ||
    extractTag(block, 'content')
  ).substring(0, 600);
  const dateStr = extractTag(block, 'pubDate') ||
    extractTag(block, 'published') ||
    extractTag(block, 'updated') ||
    extractTag(block, 'dc:date');

  if (dateStr) {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime()) && d < cutoff) continue;
  }

  if (title && title.length > 5) {
    items.push({
      title,
      link: link.trim(),
      description: desc,
      pub_date: dateStr,
      source_name: feedMeta.name,
      source_tier: feedMeta.tier,
      source_category: feedMeta.category,
      fetched_at: now.toISOString()
    });
  }
}

return items.map(i => ({ json: i }));

// Collect all parsed items from the loop and deduplicate by title
const items = $input.all().map(i => i.json);
const seen = new Set();
const unique = [];

for (const item of items) {
  const key = item.title.toLowerCase().substring(0, 80);
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}

// Store total count for digest
const totalCount = unique.length;

return unique.map((item, idx) => ({
  json: { ...item, _batch_total: totalCount, _batch_index: idx }
}));

