// Parse Claude response and merge with original item
const claudeRaw = $input.item.json;
const original = $('Deduplicate').item.json;

let parsed;
try {
  const text = claudeRaw.content?.[0]?.text || '';
  const cleaned = text.replace(/```json\n?|```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch {
  parsed = { score: 5, reason: 'Unparseable response', category: 'unknown', newsletter_tier: 'all', newsletter_angle: 'Review manually' };
}

return {
  json: {
    ...original,
    relevance_score: parsed.score || 5,
    score_reason: parsed.reason || '',
    ai_category: parsed.category || 'unknown',
    newsletter_tier: parsed.newsletter_tier || 'all',
    newsletter_angle: parsed.newsletter_angle || ''
  }
};

// Build daily digest summary
const scored = $('Merge Scores').all();
const passed = $('Score >= 7').all();

const byCategory = {};
for (const item of passed) {
  const cat = item.json.ai_category || 'unknown';
  byCategory[cat] = (byCategory[cat] || 0) + 1;
}

const catBreakdown = Object.entries(byCategory)
  .sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  ${c}: ${n}`)
  .join('\n');

const topItems = [...passed]
  .sort((a, b) => (b.json.relevance_score || 0) - (a.json.relevance_score || 0))
  .slice(0, 5)
  .map(i => `  [${i.json.relevance_score}] ${i.json.title}\n       → ${i.json.newsletter_angle}`)
  .join('\n');

const d = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });

return { json: {
  summary: `📡 Ecosystem Scanner — ${d}\n\n` +
    `Scanned ${scored.length} items → ${passed.length} passed (score ≥ 7)\n\n` +
    `Categories:\n${catBreakdown || '  (none)'}\n\n` +
    `Top signals:\n${topItems || '  (none today)'}`,
  items_found: passed.length,
  total_scanned: scored.length
}};
